(() => {
  const swRoutes = {
      uv: ['/uv/sw.js', '/uv/sw-blacklist.js'],
      sj: [
        'https://cdn.jsdelivr.net/gh/AerialiteLabs/Holy-Unblocker@6.9.3/views/dist/scram/scramjet.sw.js',
        'https://cdn.jsdelivr.net/gh/AerialiteLabs/Holy-Unblocker@6.9.3/views/dist/scram/scramjet.sw-blacklist.js'
      ],
    },
    swAllowedHostnames = ['localhost', '127.0.0.1'],
    wispUrl =
      (location.protocol === 'https:' ? 'wss' : 'ws') +
      '://' +
      location.host +
      '/wisp/',
    proxyUrl = {
      tor: 'socks5h://localhost:9050',
      eu: 'socks5h://localhost:7000',
      usWest: 'socks5h://localhost:7001',
      usEast: 'socks5h://localhost:7002',
      jp: 'socks5h://localhost:7003',
    },
    transports = {
      'epoxy': 'https://cdn.jsdelivr.net/npm/@mercuryworkshop/epoxy-transport/dist/index.mjs',
      'libcurl': 'https://cdn.jsdelivr.net/npm/@mercuryworkshop/libcurl-transport/dist/index.mjs',
    },
    storageId = 'hu-lts-storage',
    storageObject = () => JSON.parse(localStorage.getItem(storageId)) || {},
    readStorage = (name) => storageObject()[name],
    defaultMode = /(?:Chrome|AppleWebKit)\//.test(navigator.userAgent)
      ? 'epoxy'
      : 'libcurl';

  transports.default = transports[defaultMode];

  Object.freeze(transports);

  const registerSW = async () => {
    if (!navigator.serviceWorker) {
      if (
        location.protocol !== 'https:' &&
        !swAllowedHostnames.includes(location.hostname)
      )
        throw new Error('Service workers cannot be registered without https.');

      throw new Error("Your browser doesn't support service workers.");
    }

    // Set the transport mode
    const transportMode =
      transports[readStorage('Transport')] || transports.default;
    let transportOptions = { wisp: wispUrl };

    // Socks5 proxy options
    if ('string' === typeof readStorage('UseSocks5'))
      transportOptions.proxy = proxyUrl[readStorage('UseSocks5')];

    console.log('Using proxy:', transportOptions.proxy);
    console.log('Transport mode:', transportMode);

    const bareworker = `data:application/javascript;base64,`;
    const connection = new BareMux.BareMuxConnection(bareworker);
    await connection.setTransport(transportMode, [transportOptions]);

    const registrations = await navigator.serviceWorker.getRegistrations(),
      usedSW = swRoutes.uv[readStorage('HideAds') !== false ? 1 : 0];

    console.log('Service Worker being registered:', usedSW);

    // Unregister outdated service workers
    for (const registration of registrations)
      if (
        registration.active &&
        new URL(registration.active.scriptURL).pathname !==
          new URL(usedSW, location.origin).pathname
      )
        await registration.unregister();

    await navigator.serviceWorker.register(usedSW);
  };

  const initializeScramjet = async () => {
    try {
      const { ScramjetController } = await $scramjetLoadController();

      const scramjet = new ScramjetController({
        prefix: '/scram/network/',
        files: {
          wasm: "https://cdn.jsdelivr.net/gh/AerialiteLabs/scramjet-static@latest/dist/scramjet.wasm.wasm",
          all: "https://cdn.jsdelivr.net/gh/AerialiteLabs/scramjet-static@latest/dist/scramjet.all.js",
          sync: "https://cdn.jsdelivr.net/gh/AerialiteLabs/scramjet-static@latest/dist/scramjet.sync.js",
        },
        flags: {
          rewriterLogs: false,
          naiiveRewriter: false,
          scramitize: false,
        },
      });

      console.log('Initializing ScramjetController');
      scramjet.init();
      navigator.serviceWorker.register(
        swRoutes.sj[readStorage('HideAds') !== false ? 1 : 0]
      );
    } catch (err) {
      console.error('Scramjet initialization failed:', err);
    }
  };

  const initialize = async () => {
    try {
      await registerSW();

      await initializeScramjet();
    } catch (err) {
      console.error('Initialization failed:', err);
    }
  };

  initialize();
})();
